INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('144baed8-ce85-5367-9a20-3f4350900dc2', 'Colombia Sovereign Green Bond Framework', 'Colombia Sovereign Green Bond Framework', 'This Green Bond Framework, together with the issuance of sov­ereign green bonds in Colombia, constitute a key element in the development of the country’s green bond market. Finally, the Framework is aligned with the International Capital Markets Association’s (ICMA) Green Bond Principles (GBP).', 'This Green Bond Framework, together with the issuance of sov­ereign green bonds in Colombia, constitute a key element in the development of the country’s green bond market. Finally, the Framework is aligned with the International Capital Markets Association’s (ICMA) Green Bond Principles (GBP).', 'This Green Bond Framework, together with the issuance of sov­ereign green bonds in Colombia, constitute a key element in the development of the country’s green bond market. Finally, the Framework is aligned with the International Capital Markets Association’s (ICMA) Green Bond Principles (GBP).', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_54', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'sdg7', 'sdg11', 'voluntary', 'colombia', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d0887a45-a6a7-567c-ae45-5512950e8127', 'Colombia Technical Document Disclosure of sustainability or ESG information', 'Technical Document Disclosure of sustainability or ESG information in Colombia', 'The Documento Técnico Divulgación de Información de Sostenibilidad o ESG en Colombia provides technical guidance for companies in Colombia on how to disclose their environmental, social, and governance (ESG) practices. The document outlines the key principles, frameworks, and standards that companies can use to report on their ESG performance, such as the Global Reporting Initiative (GRI) and the Task Force on Climate-related Financial Disclosures (TCFD). It also provides specific guidance on how to report on topics such as climate change, human rights, and supply chain management. The goal of the document is to promote transparency and accountability among companies and to encourage the integration of ESG considerations into business decision-making.', 'The Documento Técnico Divulgación de Información de Sostenibilidad o ESG en Colombia provides technical guidance for companies in Colombia on how to disclose their environmental, social, and governance (ESG) practices. The document outlines the key principles, frameworks, and standards that companies can use to report on their ESG performance, such as the Global Reporting Initiative (GRI) and the Task Force on Climate-related Financial Disclosures (TCFD). It also provides specific guidance on how to report on topics such as climate change, human rights, and supply chain management. The goal of the document is to promote transparency and accountability among companies and to encourage the integration of ESG considerations into business decision-making.', 'The Documento Técnico Divulgación de Información de Sostenibilidad o ESG en Colombia provides technical guidance for companies in Colombia on how to disclose their environmental, social, and governance (ESG) practices. The document outlines the key principles, frameworks, and standards that companies can use to report on their ESG performance, such as the Global Reporting Initiative (GRI) and the Task Force on Climate-related Financial Disclosures (TCFD). It also provides specific guidance on how to report on topics such as climate change, human rights, and supply chain management. The goal of the document is to promote transparency and accountability among companies and to encourage the integration of ESG considerations into business decision-making.', 'Colombia', 'climate', 'in_force', '2021-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_55', ARRAY['sdg13', 'regulations', 'mandatory', 'colombia', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f11e66b9-e327-5582-ac79-fe22f709b5e4', 'Colombia Guide for the Preparation of ESG Reports', 'Guide for the Preparation of ESG Reports for Issuers in Colombia', 'This document is not intended to duplicate efforts with respect to existing reporting standards, but rather to provide guidelines to improve the quantity, quality, consistency and depth of the information reported to the financial sector following the GRI Standards, the most widely used sustainability reporting standards.', 'This document is not intended to duplicate efforts with respect to existing reporting standards, but rather to provide guidelines to improve the quantity, quality, consistency and depth of the information reported to the financial sector following the GRI Standards, the most widely used sustainability reporting standards.', 'This document is not intended to duplicate efforts with respect to existing reporting standards, but rather to provide guidelines to improve the quantity, quality, consistency and depth of the information reported to the financial sector following the GRI Standards, the most widely used sustainability reporting standards.', 'Colombia', 'climate', 'in_force', '2020-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_17', ARRAY['sdg13', 'other sustainability policy', 'sdg17', 'mandatory', 'colombia', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5e320e78-dcf2-534d-82da-09e860810969', 'Legal Guide to Do Business in Colombia', 'Legal Guide to Do Business in Colombia 2020', 'This Legal Guide to do Business in Colombia (the “Guide”) provides foreign investors guidelines on the main legal aspects. The content of this document was prepared and updated in March 2020, based entirely on the current information and legislation.', 'This Legal Guide to do Business in Colombia (the “Guide”) provides foreign investors guidelines on the main legal aspects. The content of this document was prepared and updated in March 2020, based entirely on the current information and legislation.', 'This Legal Guide to do Business in Colombia (the “Guide”) provides foreign investors guidelines on the main legal aspects. The content of this document was prepared and updated in March 2020, based entirely on the current information and legislation.', 'Colombia', 'circularity', 'in_force', '2020-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_7', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'colombia', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3f8bee93-207c-5848-a13b-4c19b6501935', 'Colombia Technical document of good practices for the analysis', 'Technical document of good practices for the analysis of investment in private equity funds.', 'The purpose of this document is to present the best international practices incorporated in the due diligence processes for investment in private equity funds, by institutional investors, in order for them to be implemented by the administrators of the Individual Savings Regime with Solidarity - RAIS.', 'The purpose of this document is to present the best international practices incorporated in the due diligence processes for investment in private equity funds, by institutional investors, in order for them to be implemented by the administrators of the Individual Savings Regime with Solidarity - RAIS.', 'The purpose of this document is to present the best international practices incorporated in the due diligence processes for investment in private equity funds, by institutional investors, in order for them to be implemented by the administrators of the Individual Savings Regime with Solidarity - RAIS.', 'Colombia', 'governance', 'in_force', '2019-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_13', ARRAY['colombia', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6e122408-d692-510a-b09c-a9c83c380928', 'Colombia National Development Plan 2018 - 2022 "Pact', 'National Development Plan 2018 - 2022 "Pact for Colombia, Pact for Equity"', 'The National Development Plan 2018-2022 "Pact for Colombia, pact for equity", which is issued by means of this law, aims to lay the foundations of legality, entrepreneurship and equity that allow achieving equal opportunities for all.', 'The National Development Plan 2018-2022 "Pact for Colombia, pact for equity", which is issued by means of this law, aims to lay the foundations of legality, entrepreneurship and equity that allow achieving equal opportunities for all.', 'The National Development Plan 2018-2022 "Pact for Colombia, pact for equity", which is issued by means of this law, aims to lay the foundations of legality, entrepreneurship and equity that allow achieving equal opportunities for all.', 'Colombia', 'climate', 'in_force', '2018-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_16', ARRAY['sdg4', 'sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg5', 'colombia', 'sdg16', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('68378b6d-57db-5b5d-8216-659f87b7b429', 'Colombia Resolution', 'Resolution No 00040207', 'In 2018, the Colombian government issued "Resolución No 00040207," which is a resolution that establishes the technical requirements and procedures for the registration and certification of renewable energy projects in the country. The resolution outlines the information that must be included in project proposals, as well as the criteria that will be used to evaluate them. It also establishes procedures for monitoring and verifying the performance of registered projects, as well as the process for renewing or revoking project certifications. Overall, the resolution aims to promote the development of renewable energy projects in Colombia and ensure their compliance with technical and environmental standards.', 'In 2018, the Colombian government issued "Resolución No 00040207," which is a resolution that establishes the technical requirements and procedures for the registration and certification of renewable energy projects in the country. The resolution outlines the information that must be included in project proposals, as well as the criteria that will be used to evaluate them. It also establishes procedures for monitoring and verifying the performance of registered projects, as well as the process for renewing or revoking project certifications. Overall, the resolution aims to promote the development of renewable energy projects in Colombia and ensure their compliance with technical and environmental standards.', 'In 2018, the Colombian government issued "Resolución No 00040207," which is a resolution that establishes the technical requirements and procedures for the registration and certification of renewable energy projects in the country. The resolution outlines the information that must be included in project proposals, as well as the criteria that will be used to evaluate them. It also establishes procedures for monitoring and verifying the performance of registered projects, as well as the process for renewing or revoking project certifications. Overall, the resolution aims to promote the development of renewable energy projects in Colombia and ensure their compliance with technical and environmental standards.', 'Colombia', 'climate', 'in_force', '2018-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_36', ARRAY['sdg2', 'other sustainability policy', 'sdg7', 'mandatory', 'colombia', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
