INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0583c1bd-f4e8-51c7-9e0c-97b7fc99dcda', 'Colombia Decree Number 1076', 'Decree Number 1076', 'In 2015, the Colombian government issued "Decreto Número 1076," which is a decree that establishes the rules and procedures for land use planning in the country. The decree outlines the process for developing and implementing land use plans, as well as the responsibilities of different government entities and stakeholders involved in the process. It also establishes guidelines for the allocation and use of land, including environmental considerations, and sets out procedures for resolving disputes related to land use.', 'In 2015, the Colombian government issued "Decreto Número 1076," which is a decree that establishes the rules and procedures for land use planning in the country. The decree outlines the process for developing and implementing land use plans, as well as the responsibilities of different government entities and stakeholders involved in the process. It also establishes guidelines for the allocation and use of land, including environmental considerations, and sets out procedures for resolving disputes related to land use.', 'In 2015, the Colombian government issued "Decreto Número 1076," which is a decree that establishes the rules and procedures for land use planning in the country. The decree outlines the process for developing and implementing land use plans, as well as the responsibilities of different government entities and stakeholders involved in the process. It also establishes guidelines for the allocation and use of land, including environmental considerations, and sets out procedures for resolving disputes related to land use.', 'Colombia', 'nature', 'in_force', '2015-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_21', ARRAY['regulations', 'mandatory', 'col