INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('721e62a9-76b3-5c51-ba20-6d3ea93637b4', 'Colombia Resolution 631', 'Resolution 631', 'This Resolution establishes the parameters and the maximum permissible limit values that must be complied with by those who discharge punctual discharges into surface water bodies and public sewage systems.', 'This Resolution establishes the parameters and the maximum permissible limit values that must be complied with by those who discharge punctual discharges into surface water bodies and public sewage systems.', 'This Resolution establishes the parameters and the maximum permissible limit values that must be complied with by those who discharge punctual discharges into surface water bodies and public sewage systems.', 'Colombia', 'governance', 'in_force', '2015-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_27', ARRAY['other sustainability policy', 'mandatory', 'sdg6', 'colombia', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46d55bbb-3c9d-5e40-a94c-98091c23586b', 'Legal Guide to Do Business in Colombia', 'Legal Guide to Do Business in Colombia 2015', 'This guide provides foreign investors with guidelines on the main legal aspects of doing business in Colombia, as well as key economic and social indicators.', 'This guide provides foreign investors with guidelines on the main legal aspects of doing business in Colombia, as well as key economic and social indicators.', 'This guide provides foreign investors with guidelines on the main legal aspects of doing business in Colombia, as well as key economic and social indicators.', 'Colombia', 'governance', 'in_force', '2015-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_3', ARRAY['guidance_frameworks', 'mandatory', 'colombia', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2c23a2c6-6eac-58b1-af26-9e9665793eeb', 'Colombia Decree 1076', 'Decree 1076', 'A decree through which the Sole Regulatory Decree of the Environment and Sustainable Development Sector is issued.', 'A decree through which the Sole Regulatory Decree of the Environment and Sustainable Development Sector is issued.', 'A decree through which the Sole Regulatory Decree of the Environment and Sustainable Development Sector is issued.', 'Colombia', 'climate', 'in_force', '2015-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_31', ARRAY['sdg13', 'regulations', 'mandatory', 'colombia', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c0d16143-7fd3-511c-b472-589907a9546a', 'Colombia Code of Best Corporate Governance Practices', 'Code of Best Corporate Governance Practices', 'In its formal structure, the new Country Code is similar to its 2007 version. Consequently, it still identifies five (5) major Corporate Governance areas, and within them, thirty-three (33) concrete measures on key governance aspects. For better understanding and progression, some measures are divided into several recommendations, which are enumerated on a sequential basis. Therefore, the Country Code proposes up to one hundred and forty-eight (148) Corporate Governance recommendations.', 'In its formal structure, the new Country Code is similar to its 2007 version. Consequently, it still identifies five (5) major Corporate Governance areas, and within them, thirty-three (33) concrete measures on key governance aspects. For better understanding and progression, some measures are divided into several recommendations, which are enumerated on a sequential basis. Therefore, the Country Code proposes up to one hundred and forty-eight (148) Corporate Governance recommendations.', 'In its formal structure, the new Country Code is similar to its 2007 version. Consequently, it still identifies five (5) major Corporate Governance areas, and within them, thirty-three (33) concrete measures on key governance aspects. For better understanding and progression, some measures are divided into several recommendations, which are enumerated on a sequential basis. Therefore, the Country Code proposes up to one hundred and forty-eight (148) Corporate Governance recommendations.', 'Colombia', 'governance', 'in_force', '2014-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_2', ARRAY['regulations', 'mandatory', 'colombia', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8cd64c27-1dc5-5d7b-878b-d1bd9cff9628', 'Colombia Responsible And Sustainable Investing: Overview Current Practices And', 'Responsible And Sustainable Investing: Overview Current Practices And Trends', 'This report presents an approach to the tendencies, the motivations, and the characteristics of the IRS globally and the IRS in relation to the Latin American context. In addition, the report proposes actions that seek to break the inertia and move towards a scenario where the creation of individual value considers and contributes to a system with better general conditions. This implies, to a certain extent, a paradigm shift; but it is certainly a necessary change in the search for prosperous Latin American societies, in which value is generated by a sustainable competitive private sector.', 'This report presents an approach to the tendencies, the motivations, and the characteristics of the IRS globally and the IRS in relation to the Latin American context. In addition, the report proposes actions that seek to break the inertia and move towards a scenario where the creation of individual value considers and contributes to a system with better general conditions. This implies, to a certain extent, a paradigm shift; but it is certainly a necessary change in the search for prosperous Latin American societies, in which value is generated by a sustainable competitive private sector.', 'This report presents an approach to the tendencies, the motivations, and the characteristics of the IRS globally and the IRS in relation to the Latin American context. In addition, the report proposes actions that seek to break the inertia and move towards a scenario where the creation of individual value considers and contributes to a system with better general conditions. This implies, to a certain extent, a paradigm shift; but it is certainly a necessary change in the search for prosperous Latin American societies, in which value is generated by a sustainable competitive private sector.', 'Colombia', 'climate', 'in_force', '2014-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_8', ARRAY['sdg14', 'regulations', 'mandatory', 'colombia', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9f9f0151-7614-58b4-9cfe-823d9271fc94', 'Colombia External Circular 028 of 2014. Presentation of the', 'External Circular 028 of 2014. Presentation of the new Country Code and the Implementation Report of the Best Corporate Governance Practices', 'Taking into consideration the developments in Corporate Governance globally, and in order to meet new business circumstances, particularly after the world economic crisis which revealed, among many other things, the deep weaknesses that lingered in the Corporate Governance functioning, the Financial Superintendency of Colombia (FSC) has led a process of revision of the Country Code, taken as a key referent the CAF’s publication “Lineamientos para un Código Latinoamericano de Gobierno Corporativo” [Guidelines for a Latin American Corporate Governance Code], as well as the comments and input from the industry, to develop a new Country Code that suits the Colombian market situation. This Office, in using of its powers, especially those establishes in paragraph a) of Article 6 of Law 964 of 2005 and paragraph 9 of Article 11.2.1.4.2 of Decree 2555 of 2010, considers it appropriate to present the new Code of Best Corporate Governance Practices of Colombia (hereinafter New Country Code) and establishes the obligation to fill in and submit the Implementation Report.', 'Taking into consideration the developments in Corporate Governance globally, and in order to meet new business circumstances, particularly after the world economic crisis which revealed, among many other things, the deep weaknesses that lingered in the Corporate Governance functioning, the Financial Superintendency of Colombia (FSC) has led a process of revision of the Country Code, taken as a key referent the CAF’s publication “Lineamientos para un Código Latinoamericano de Gobierno Corporativo” [Guidelines for a Latin American Corporate Governance Code], as well as the comments and input from the industry, to develop a new Country Code that suits the Colombian market situation. This Office, in using of its powers, especially those establishes in paragraph a) of Article 6 of Law 964 of 2005 and paragraph 9 of Article 11.2.1.4.2 of Decree 2555 of 2010, considers it appropriate to present the new Code of Best Corporate Governance Practices of Colombia (hereinafter New Country Code) and establishes the obligation to fill in and submit the Implementation Report.', 'Taking into consideration the developments in Corporate Governance globally, and in order to meet new business circumstances, particularly after the world economic crisis which revealed, among many other things, the deep weaknesses that lingered in the Corporate Governance functioning, the Financial Superintendency of Colombia (FSC) has led a process of revision of the Country Code, taken as a key referent the CAF’s publication “Lineamientos para un Código Latinoamericano de Gobierno Corporativo” [Guidelines for a Latin American Corporate Governance Code], as well as the comments and input from the industry, to develop a new Country Code that suits the Colombian market situation. This Office, in using of its powers, especially those establishes in paragraph a) of Article 6 of Law 964 of 2005 and paragraph 9 of Article 11.2.1.4.2 of Decree 2555 of 2010, considers it appropriate to present the new Code of Best Corporate Governance Practices of Colombia (hereinafter New Country Code) and establishes the obligation to fill in and submit the Implementation Report.', 'Colombia', 'climate', 'in_force', '2014-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_9', ARRAY['regulations', 'mandatory', 'colombia', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d52eff17-7be3-57e0-99f9-9266a0c2cdcd', 'Colombian Low Carbon Development Strategy', 'Colombian Low Carbon Development Strategy 2013', 'The Strategy seeks to: 1) identify and assess actions that will be aimed at avoiding the accelerated growth of GHG emissions as the sectors grow, 2) develop mitigation action plans in each productive sector of the country, and 3) promote the tools for its implementation, including a monitoring and reporting system.', 'The Strategy seeks to: 1) identify and assess actions that will be aimed at avoiding the accelerated growth of GHG emissions as the sectors grow, 2) develop mitigation action plans in each productive sector of the country, and 3) promote the tools for its implementation, including a monitoring and reporting system.', 'The Strategy seeks to: 1) identify and assess actions that will be aimed at avoiding the accelerated growth of GHG emissions as the sectors grow, 2) develop mitigation action plans in each productive sector of the country, and 3) promote the tools for its implementation, including a monitoring and reporting system.', 'Colombia', 'climate', 'in_force', '2013-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_14', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'sdg7', 'sdg11', 'mandatory', 'colombia', 'mandatory_regulations', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('024311f4-a109-5e7b-a04c-86c52822fbd4', 'Colombia Resolution 1514', 'Resolution 1514', 'The objective of this resolution is to promote the technical and operational safety of the Discharge Management System (processes and flows of the activity), to avoid affecting the environmental and social conditions of the area of influence, in the event of a discharge in conditions that prevent or limit the compliance with the discharge standard.', 'The objective of this resolution is to promote the technical and operational safety of the Discharge Management System (processes and flows of the activity), to avoid affecting the environmental and social conditions of the area of influence, in the event of a discharge in conditions that prevent or limit the compliance with the discharge standard.', 'The objective of this resolution is to promote the technical and operational safety of the Discharge Management System (processes and flows of the activity), to avoid affecting the environmental and social conditions of the area of influence, in the event of a discharge in conditions that prevent or limit the compliance with the discharge standard.', 'Colombia', 'climate', 'in_force', '2012-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_37', ARRAY['sdg13', 'regulations', 'mandatory', 'colombia', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0fb45769-8995-5bec-9491-c75e54cb8151', 'Colombian Low Carbon Development Strategy', 'Colombian Low Carbon Development Strategy 2012', 'The Colombian Strategy for Low Carbon Development (ECDBC) is a program of short, medium and long term for development planning, which seeks to decouple the growth of emissions greenhouse gas (GHG) from national economic growth. The Colombian Strategy for Low Carbon Development (ECDBC) is a program of short, medium and long term for development planning, which seeks to decouple the growth of emissions greenhouse gas (GHG) from national economic growth. This will be done through the design and implementation of sectoral mitigation measures to maximize the carbon-efficiency of economic activity and, in turn, contribute to national social and economic development. The objectives of the ECDBC are to identify and evaluate actions to prevent the rapid growth of GHG emissions as sectors growing, developing action plans for mitigation in each productive sector, promoting implementation tools, including a monitoring and reporting system.', 'The Colombian Strategy for Low Carbon Development (ECDBC) is a program of short, medium and long term for development planning, which seeks to decouple the growth of emissions greenhouse gas (GHG) from national economic growth. The Colombian Strategy for Low Carbon Development (ECDBC) is a program of short, medium and long term for development planning, which seeks to decouple the growth of emissions greenhouse gas (GHG) from national economic growth. This will be done through the design and implementation of sectoral mitigation measures to maximize the carbon-efficiency of economic activity and, in turn, contribute to national social and economic development. The objectives of the ECDBC are to identify and evaluate actions to prevent the rapid growth of GHG emissions as sectors growing, developing action plans for mitigation in each productive sector, promoting implementation tools, including a monitoring and reporting system.', 'The Colombian Strategy for Low Carbon Development (ECDBC) is a program of short, medium and long term for development planning, which seeks to decouple the growth of emissions greenhouse gas (GHG) from national economic growth. The Colombian Strategy for Low Carbon Development (ECDBC) is a program of short, medium and long term for development planning, which seeks to decouple the growth of emissions greenhouse gas (GHG) from national economic growth. This will be done through the design and implementation of sectoral mitigation measures to maximize the carbon-efficiency of economic activity and, in turn, contribute to national social and economic development. The objectives of the ECDBC are to identify and evaluate actions to prevent the rapid growth of GHG emissions as sectors growing, developing action plans for mitigation in each productive sector, promoting implementation tools, including a monitoring and reporting system.', 'Colombia', 'climate', 'in_force', '2012-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_4', ARRAY['sdg2', 'sdg13', 'sdg7', 'mandatory', 'colombia', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg15', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5924d317-0708-5b47-b2e7-77c045d48455', 'Colombia Decree 2820 "By which Title VIII of Law', 'Decree 2820 "By which Title VIII of Law 99 of 1993 on environmental licenses is regulated"', 'This law decree is about the concept and score of the Environmental License, which must be obtained prior to the initiation of the project or work. The Environmental License will implicitly include all permits, authorizations and concessions for the use, exploitation and/or affectation of renewable natural resources.', 'This law decree is about the concept and score of the Environmental License, which must be obtained prior to the initiation of the project or work. The Environmental License will implicitly include all permits, authorizations and concessions for the use, exploitation and/or affectation of renewable natural resources.', 'This law decree is about the concept and score of the Environmental License, which must be obtained prior to the initiation of the project or work. The Environmental License will implicitly include all permits, authorizations and concessions for the use, exploitation and/or affectation of renewable natural resources.', 'Colombia', 'climate', 'in_force', '2010-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_24', ARRAY['sdg14', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'colombia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('34bf8aac-ca1d-5109-ad14-a53ebc05c184', 'Colombia Resolution 1512', 'Resolution 1512', 'The purpose of this resolution is to establish, by the producers of computers and/or peripherals that are marketed in the country, the obligation to formulate, present and implement the Selective Collection Systems and Environmental Management of Waste from  Computers and/or Peripherals, for the purpose of preventing and controlling environmental  degradation.', 'The purpose of this resolution is to establish, by the producers of computers and/or peripherals that are marketed in the country, the obligation to formulate, present and implement the Selective Collection Systems and Environmental Management of Waste from  Computers and/or Peripherals, for the purpose of preventing and controlling environmental  degradation.', 'The purpose of this resolution is to establish, by the producers of computers and/or peripherals that are marketed in the country, the obligation to formulate, present and implement the Selective Collection Systems and Environmental Management of Waste from  Computers and/or Peripherals, for the purpose of preventing and controlling environmental  degradation.', 'Colombia', 'circularity', 'in_force', '2010-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_35', ARRAY['mandatory', 'colombia', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('22a1f05a-efe6-5dea-a626-fee24a52e43c', 'Colombia Decree 3930', 'Decree 3930', 'A decree by which Title I of Law 9 of 1979 is partially regulated, as well as Chapter II of Title VI -Part III- Book II of Decree-Law 2811 of 1974 regarding the uses of water and liquid waste and other provisions.', 'A decree by which Title I of Law 9 of 1979 is partially regulated, as well as Chapter II of Title VI -Part III- Book II of Decree-Law 2811 of 1974 regarding the uses of water and liquid waste and other provisions.', 'A decree by which Title I of Law 9 of 1979 is partially regulated, as well as Chapter II of Title VI -Part III- Book II of Decree-Law 2811 of 1974 regarding the uses of water and liquid waste and other provisions.', 'Colombia', 'climate', 'in_force', '2010-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_38', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'colombia', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('881cb194-f613-53f8-a345-cbfee24ea5cc', 'Colombian Guide to Corporate Governance for Closed', 'Colombian Guide to Corporate Governance for Closed and Family Companies', 'This Guide is the first model of good Corporate Governance practices that has been designed with the express purpose of reducing or eliminating the occurrence of previously detected irregularities.', 'This Guide is the first model of good Corporate Governance practices that has been designed with the express purpose of reducing or eliminating the occurrence of previously detected irregularities.', 'This Guide is the first model of good Corporate Governance practices that has been designed with the express purpose of reducing or eliminating the occurrence of previously detected irregularities.', 'Colombia', 'governance', 'in_force', '2009-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_11', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'colombia', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('545c4036-8a71-5960-8ba1-3746570305cc', 'Colombia Commercial Code (modified up to Law of July', 'Commercial Code (modified up to Law No. 1328 of July 15, 2009)', 'The Colombian Commercial Code, enacted in 1971, is the main legal framework for commercial activities in Colombia. It underwent a major revision in 2009, which updated and modernized many of its provisions. The code covers a wide range of commercial matters, including commercial contracts, negotiable instruments, commercial entities, bankruptcy, and commercial arbitration. It also provides regulations for commercial practices such as sales, insurance, transportation, and banking. The code sets out the obligations of businesses in Colombia, including the registration of commercial entities, compliance with accounting and financial reporting standards, and adherence to fair competition practices.', 'The Colombian Commercial Code, enacted in 1971, is the main legal framework for commercial activities in Colombia. It underwent a major revision in 2009, which updated and modernized many of its provisions. The code covers a wide range of commercial matters, including commercial contracts, negotiable instruments, commercial entities, bankruptcy, and commercial arbitration. It also provides regulations for commercial practices such as sales, insurance, transportation, and banking. The code sets out the obligations of businesses in Colombia, including the registration of commercial entities, compliance with accounting and financial reporting standards, and adherence to fair competition practices.', 'The Colombian Commercial Code, enacted in 1971, is the main legal framework for commercial activities in Colombia. It underwent a major revision in 2009, which updated and modernized many of its provisions. The code covers a wide range of commercial matters, including commercial contracts, negotiable instruments, commercial entities, bankruptcy, and commercial arbitration. It also provides regulations for commercial practices such as sales, insurance, transportation, and banking. The code sets out the obligations of businesses in Colombia, including the registration of commercial entities, compliance with accounting and financial reporting standards, and adherence to fair competition practices.', 'Colombia', 'climate', 'in_force', '2009-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_20', ARRAY['regulations', 'sdg11', 'mandatory', 'colombia', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46f76ca8-6577-53a1-b2e4-684e2e802d6d', 'Colombia Code of Best Corporate Practices', 'Code of Best Corporate Practices', 'The Code has been structured in such a way that it contains a set of specific measures, which are expected to be incorporated by the issuers of securities in their daily activity, on the following topics: (i) General Assembly of Shareholders, (ii) Board of Directors, ( iii) Disclosure of Financial and Non-Financial Information, and (iv) Dispute Resolution. Each group of measures is preceded by a brief explanation of them.', 'The Code has been structured in such a way that it contains a set of specific measures, which are expected to be incorporated by the issuers of securities in their daily activity, on the following topics: (i) General Assembly of Shareholders, (ii) Board of Directors, ( iii) Disclosure of Financial and Non-Financial Information, and (iv) Dispute Resolution. Each group of measures is preceded by a brief explanation of them.', 'The Code has been structured in such a way that it contains a set of specific measures, which are expected to be incorporated by the issuers of securities in their daily activity, on the following topics: (i) General Assembly of Shareholders, (ii) Board of Directors, ( iii) Disclosure of Financial and Non-Financial Information, and (iv) Dispute Resolution. Each group of measures is preceded by a brief explanation of them.', 'Colombia', 'governance', 'in_force', '2007-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_10', ARRAY['disclosure', 'colombia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e8e69a25-60a3-5432-97b8-9dc3269ac59f', 'Colombia Decree 4741', 'Decree 4741', 'This Decree partially regulates the prevention and management of waste or hazardous waste generated within the framework of comprehensive management.', 'This Decree partially regulates the prevention and management of waste or hazardous waste generated within the framework of comprehensive management.', 'This Decree partially regulates the prevention and management of waste or hazardous waste generated within the framework of comprehensive management.', 'Colombia', 'circularity', 'in_force', '2005-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_28', ARRAY['regulations', 'mandatory', 'colombia', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bb576da8-aeb9-50fb-b0c4-b0266905c3ea', 'Colombia Resolution 1552', 'Resolution 1552', 'A resolution by which the manuals for the evaluation of Environmental Studies and environmental monitoring of the Project are adopted and other determinations are made.', 'A resolution by which the manuals for the evaluation of Environmental Studies and environmental monitoring of the Project are adopted and other determinations are made.', 'A resolution by which the manuals for the evaluation of Environmental Studies and environmental monitoring of the Project are adopted and other determinations are made.', 'Colombia', 'governance', 'in_force', '2005-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_30', ARRAY['mandatory', 'other sustainability policy', 'mandatory_regulations', 'colombia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('636ecf95-544f-540a-a3ee-c4d449831e05', 'Colombia Framework Code of Good Corporate Governance for Small', 'Framework Code of Good Corporate Governance for Small and Medium-Size Enterprises', 'The paper is an original tool for introducing the concept of corporate governance to the Latin American environment.', 'The paper is an original tool for introducing the concept of corporate governance to the Latin American environment.', 'The paper is an original tool for introducing the concept of corporate governance to the Latin American environment.', 'Colombia', 'governance', 'in_force', '2004-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_12', ARRAY['voluntary', 'colombia', 'sdg16', 'disclosure', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6d78519e-ce7d-59ad-b062-bc7ffa590c56', 'Colombia Decree 1791', 'Decree 1791', 'Decree 1791 of 1996 in Colombia establishes the forest exploitation regime to regulate activities regarding the use, management, exploitation, and conservation of forests and wild flora for sustainable development. The decree outlines definitions, principles, and priorities for forest use, emphasizing sustainability and the coordination between state, community, and private sector. It aims to support investments in environmental matters and forestry sector development while considering regional environmental, social, and economic particularities.', 'Decree 1791 of 1996 in Colombia establishes the forest exploitation regime to regulate activities regarding the use, management, exploitation, and conservation of forests and wild flora for sustainable development. The decree outlines definitions, principles, and priorities for forest use, emphasizing sustainability and the coordination between state, community, and private sector. It aims to support investments in environmental matters and forestry sector development while considering regional environmental, social, and economic particularities.', 'Decree 1791 of 1996 in Colombia establishes the forest exploitation regime to regulate activities regarding the use, management, exploitation, and conservation of forests and wild flora for sustainable development. The decree outlines definitions, principles, and priorities for forest use, emphasizing sustainability and the coordination between state, community, and private sector. It aims to support investments in environmental matters and forestry sector development while considering regional environmental, social, and economic particularities.', 'Colombia', 'climate', 'in_force', '1996-01-01'::date, 'Colombia', 'https://www.carrotsandsticks.org/policies/34_33', ARRAY['other sustainability policy', 'regulations', 'sdg9', 'sdg11', 'mandatory', 'colombia', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5966021b-9ab6-567b-93d4-53674fe7338c', 'Costa Rica Stock Exchange (BVC) Sustainability Guidelines', 'Costa Rica Stock Exchange (BVC) Sustainability Guidelines', 'The document provides a voluntary guide to help companies in Costa Rica create sustainability reports that address environmental, social, and governance (ESG) factors. The guide emphasizes the increasing interest from investors in understanding how companies manage their ESG impacts. It stresses the importance of companies integrating ESG factors into their strategies and operations to enhance transparency and accountability. Companies are encouraged to disclose information about their ESG performance, focusing on their contributions to the United Nations’ Sustainable Development Goals (SDGs). The guide offers recommendations on how to structure sustainability reports, including the need for clarity, verifiability, and comparability of the information provided. It also outlines key indicators businesses should include, such as carbon emissions, energy use, water management, employee well-being, and governance practices. The aim is to foster good governance and attract long-term investment by promoting a transparent and responsible approach to sustainability.', 'The document provides a voluntary guide to help companies in Costa Rica create sustainability reports that address environmental, social, and governance (ESG) factors. The guide emphasizes the increasing interest from investors in understanding how companies manage their ESG impacts. It stresses the importance of companies integrating ESG factors into their strategies and operations to enhance transparency and accountability. Companies are encouraged to disclose information about their ESG performance, focusing on their contributions to the United Nations’ Sustainable Development Goals (SDGs). The guide offers recommendations on how to structure sustainability reports, including the need for clarity, verifiability, and comparability of the information provided. It also outlines key indicators businesses should include, such as carbon emissions, energy use, water management, employee well-being, and governance practices. The aim is to foster good governance and attract long-term investment by promoting a transparent and responsible approach to sustainability.', 'The document provides a voluntary guide to help companies in Costa Rica create sustainability reports that address environmental, social, and governance (ESG) factors. The guide emphasizes the increasing interest from investors in understanding how companies manage their ESG impacts. It stresses the importance of companies integrating ESG factors into their strategies and operations to enhance transparency and accountability. Companies are encouraged to disclose information about their ESG performance, focusing on their contributions to the United Nations’ Sustainable Development Goals (SDGs). The guide offers recommendations on how to structure sustainability reports, including the need for clarity, verifiability, and comparability of the information provided. It also outlines key indicators businesses should include, such as carbon emissions, energy use, water management, employee well-being, and governance practices. The aim is to foster good governance and attract long-term investment by promoting a transparent and responsible approach to sustainability.', 'Costa Rica', 'climate', 'in_force', '2018-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_2', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'sdg3', 'sdg7', 'sdg6', 'sdg16', 'costa rica', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4b7a074f-f167-5fc4-9609-7a47ef1c9367', 'Costa Rica Agreement 16-16 Regulation on Corporate Governance', 'Agreement 16-16 Regulation on Corporate Governance', 'The objective of this regulation is to establish the principles on Corporate Governance that must be considered by the entities included in the scope of this Regulation. The corporate governance provisions included in this regulation are qualitative standards that faithfully reflect sound international practices, whose application depends on the particular attributes of each entity and must be applied respecting, at all times, the legal system that governs the National Financial System.', 'The objective of this regulation is to establish the principles on Corporate Governance that must be considered by the entities included in the scope of this Regulation. The corporate governance provisions included in this regulation are qualitative standards that faithfully reflect sound international practices, whose application depends on the particular attributes of each entity and must be applied respecting, at all times, the legal system that governs the National Financial System.', 'The objective of this regulation is to establish the principles on Corporate Governance that must be considered by the entities included in the scope of this Regulation. The corporate governance provisions included in this regulation are qualitative standards that faithfully reflect sound international practices, whose application depends on the particular attributes of each entity and must be applied respecting, at all times, the legal system that governs the National Financial System.', 'Costa Rica', 'governance', 'in_force', '2016-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_3', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'costa rica']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a434238e-85f7-505c-8699-02e2023c2771', 'Costa Rican National Strategy for Climate Change', 'Costa Rican National Strategy for Climate Change (2015-2050)', 'Costa Rica’s INDC outlines the country''s commitment to addressing climate change through both mitigation and adaptation efforts. The country aims to become carbon-neutral by 2021, building on its voluntary pre-2020 actions to offset emissions primarily through its forestry sector. Costa Rica has set an ambitious target to reduce its emissions by 44% from a Business-As-Usual (BAU) scenario by 2030 and is committed to achieving net emissions of no more than 9,374,000 tons of CO2 equivalent by that year. The plan also emphasizes the importance of adaptation, particularly focusing on vulnerable sectors like agriculture, water, and infrastructure, and calls for the development of a National Adaptation Plan by 2018. Costa Rica aims to utilize both domestic and international carbon markets to meet its goals. The document reflects a broad, cross-sectoral approach to reducing emissions while building resilience to climate impacts, emphasizing the use of scientific data, stakeholder involvement, and open governance.', 'Costa Rica’s INDC outlines the country''s commitment to addressing climate change through both mitigation and adaptation efforts. The country aims to become carbon-neutral by 2021, building on its voluntary pre-2020 actions to offset emissions primarily through its forestry sector. Costa Rica has set an ambitious target to reduce its emissions by 44% from a Business-As-Usual (BAU) scenario by 2030 and is committed to achieving net emissions of no more than 9,374,000 tons of CO2 equivalent by that year. The plan also emphasizes the importance of adaptation, particularly focusing on vulnerable sectors like agriculture, water, and infrastructure, and calls for the development of a National Adaptation Plan by 2018. Costa Rica aims to utilize both domestic and international carbon markets to meet its goals. The document reflects a broad, cross-sectoral approach to reducing emissions while building resilience to climate impacts, emphasizing the use of scientific data, stakeholder involvement, and open governance.', 'Costa Rica’s INDC outlines the country''s commitment to addressing climate change through both mitigation and adaptation efforts. The country aims to become carbon-neutral by 2021, building on its voluntary pre-2020 actions to offset emissions primarily through its forestry sector. Costa Rica has set an ambitious target to reduce its emissions by 44% from a Business-As-Usual (BAU) scenario by 2030 and is committed to achieving net emissions of no more than 9,374,000 tons of CO2 equivalent by that year. The plan also emphasizes the importance of adaptation, particularly focusing on vulnerable sectors like agriculture, water, and infrastructure, and calls for the development of a National Adaptation Plan by 2018. Costa Rica aims to utilize both domestic and international carbon markets to meet its goals. The document reflects a broad, cross-sectoral approach to reducing emissions while building resilience to climate impacts, emphasizing the use of scientific data, stakeholder involvement, and open governance.', 'Costa Rica', 'climate', 'in_force', '2015-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_1', ARRAY['sdg13', 'other sustainability policy', 'sdg10', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'costa rica', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f3ae62fa-9c45-5c1c-8374-1590d2032552', 'Costa Rica Decree S -- Regulation for the Quality', 'Decree No 38924-S -- Regulation for the Quality of Drinking Water', 'This Decree approves the Regulation for the quality of drinking water, which aims to establish the maximum permissible limits of physical, chemical and microbiological parameters for drinking water, in order to guarantee its safety and the health of the population. Any operator, public or private, of a drinking water supply system is subject to these regulations. The quality of water for human consumption to be used in all companies in which production processes are developed, including food, crenotherapy, recreational and agricultural activities, must comply with the maximum permissible limits established in this Regulation for physical, chemical and biological parameters. microbiological.', 'This Decree approves the Regulation for the quality of drinking water, which aims to establish the maximum permissible limits of physical, chemical and microbiological parameters for drinking water, in order to guarantee its safety and the health of the population. Any operator, public or private, of a drinking water supply system is subject to these regulations. The quality of water for human consumption to be used in all companies in which production processes are developed, including food, crenotherapy, recreational and agricultural activities, must comply with the maximum permissible limits established in this Regulation for physical, chemical and biological parameters. microbiological.', 'This Decree approves the Regulation for the quality of drinking water, which aims to establish the maximum permissible limits of physical, chemical and microbiological parameters for drinking water, in order to guarantee its safety and the health of the population. Any operator, public or private, of a drinking water supply system is subject to these regulations. The quality of water for human consumption to be used in all companies in which production processes are developed, including food, crenotherapy, recreational and agricultural activities, must comply with the maximum permissible limits established in this Regulation for physical, chemical and biological parameters. microbiological.', 'Costa Rica', 'nature', 'in_force', '2015-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_23', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'sdg12', 'costa rica', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('422dc8b8-35ac-5478-8c67-fd578fdd5f0e', 'Costa Rica Decree S — Regulation for the management', 'Decree No. 39316-S — Regulation for the management and final disposal of ordinary and special sludge and biosolids', 'This Decree approves the Regulation for the management and final disposal of ordinary and special sludge and biosolids, which does not include wastewater from sanitary huts or mobile latrines, which must be treated and comply with the provisions of the Regulation on Discharge and Wastewater Reuse. This Regulation has the following objectives: 1) protect public health and the environment; 2) regulate the final disposal of biosolids from activities.', 'This Decree approves the Regulation for the management and final disposal of ordinary and special sludge and biosolids, which does not include wastewater from sanitary huts or mobile latrines, which must be treated and comply with the provisions of the Regulation on Discharge and Wastewater Reuse. This Regulation has the following objectives: 1) protect public health and the environment; 2) regulate the final disposal of biosolids from activities.', 'This Decree approves the Regulation for the management and final disposal of ordinary and special sludge and biosolids, which does not include wastewater from sanitary huts or mobile latrines, which must be treated and comply with the provisions of the Regulation on Discharge and Wastewater Reuse. This Regulation has the following objectives: 1) protect public health and the environment; 2) regulate the final disposal of biosolids from activities.', 'Costa Rica', 'circularity', 'in_force', '2015-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_28', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'sdg12', 'costa rica', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fe5fcfd5-442f-5762-9e04-b1d1008f0a08', 'Costa Rica Declaration of Special Management Waste -- S', 'Regulation for the Declaration of Special Management Waste -- No 38272-S', 'The objectives of this regulation are: a. Establish general criteria and the general procedure for the management of waste declared as special handling waste; b. Establish the different levels of responsibility and propose forms of organization and participation in the management of special management waste by producers, importers, distributors, marketers, generators, and managers; as well as the municipalities. c. Promote, through the Compliance Plans and the Municipal Plans for Comprehensive Management of Solid Waste, the reduction of special handling waste sent to treatment and final disposal sites.', 'The objectives of this regulation are: a. Establish general criteria and the general procedure for the management of waste declared as special handling waste; b. Establish the different levels of responsibility and propose forms of organization and participation in the management of special management waste by producers, importers, distributors, marketers, generators, and managers; as well as the municipalities. c. Promote, through the Compliance Plans and the Municipal Plans for Comprehensive Management of Solid Waste, the reduction of special handling waste sent to treatment and final disposal sites.', 'The objectives of this regulation are: a. Establish general criteria and the general procedure for the management of waste declared as special handling waste; b. Establish the different levels of responsibility and propose forms of organization and participation in the management of special management waste by producers, importers, distributors, marketers, generators, and managers; as well as the municipalities. c. Promote, through the Compliance Plans and the Municipal Plans for Comprehensive Management of Solid Waste, the reduction of special handling waste sent to treatment and final disposal sites.', 'Costa Rica', 'climate', 'in_force', '2014-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_22', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg12', 'costa rica', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('12bc7f46-d4a6-5123-b0b3-bdec0ca96f23', 'Costa Rica INTE 01-01-09. Integrated management system for micro', 'INTE 01-01-09. Integrated management system for micro, small and medium enterprises (SME''s) — Requirements with guidance for its use', 'This standard establishes the requirements for an Integrated Management System (SIG) for quality and the environment in small and medium-sized enterprises (SMEs) or any other type of organization in any economic sector, when they need to ensure their competitiveness by: a) demonstrating their capacity to regularly provide products that meet customer requirements, b) avoiding, reducing or controlling (separately or in combination) the environmental impact of its activities, products and services, c) demonstrating its ability to meet legal, regulatory requirements and subscribed voluntarily by the organization applicable to its products and environmental aspects, d) aspiring to increase the satisfaction of the client and other interested parties through the application of the processes for the improvement of the system.', 'This standard establishes the requirements for an Integrated Management System (SIG) for quality and the environment in small and medium-sized enterprises (SMEs) or any other type of organization in any economic sector, when they need to ensure their competitiveness by: a) demonstrating their capacity to regularly provide products that meet customer requirements, b) avoiding, reducing or controlling (separately or in combination) the environmental impact of its activities, products and services, c) demonstrating its ability to meet legal, regulatory requirements and subscribed voluntarily by the organization applicable to its products and environmental aspects, d) aspiring to increase the satisfaction of the client and other interested parties through the application of the processes for the improvement of the system.', 'This standard establishes the requirements for an Integrated Management System (SIG) for quality and the environment in small and medium-sized enterprises (SMEs) or any other type of organization in any economic sector, when they need to ensure their competitiveness by: a) demonstrating their capacity to regularly provide products that meet customer requirements, b) avoiding, reducing or controlling (separately or in combination) the environmental impact of its activities, products and services, c) demonstrating its ability to meet legal, regulatory requirements and subscribed voluntarily by the organization applicable to its products and environmental aspects, d) aspiring to increase the satisfaction of the client and other interested parties through the application of the processes for the improvement of the system.', 'Costa Rica', 'governance', 'in_force', '2013-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_35', ARRAY['costa rica', 'guidance_frameworks', 'mandatory', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b7e48f2b-6bdd-5e6d-8891-1f909c3a268a', 'Costa Rica Reform of Regulations on Emissions of Atmospheric', 'Reform of Regulations on Emissions of Atmospheric Pollutants from Indirect Type Boilers and Furnaces No. 37301-S-MTSS- MINAET', 'This reform of the Regulation on the Emission of Atmospheric Pollutants from Indirect Type Boilers and Furnaces establishes maximum emission values for indirect boilers and furnaces that burn fossil and biomass fuels.', 'This reform of the Regulation on the Emission of Atmospheric Pollutants from Indirect Type Boilers and Furnaces establishes maximum emission values for indirect boilers and furnaces that burn fossil and biomass fuels.', 'This reform of the Regulation on the Emission of Atmospheric Pollutants from Indirect Type Boilers and Furnaces establishes maximum emission values for indirect boilers and furnaces that burn fossil and biomass fuels.', 'Costa Rica', 'climate', 'in_force', '2012-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_21', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'costa rica', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('05cece4b-3579-554a-a082-e61f458ee13b', 'Costa Rica Law - Amends Law , Law for', 'Law No. 9072 - Amends Law No. 7472, Law for the Promotion of Competition and Effective Consumer Protection', 'This Law amends the Law for the Promotion of Competition and Effective Consumer Defense, in aspects related to its field of application, absolute and relative monopolistic practices, the Commission to Promote Competition and sanctions.', 'This Law amends the Law for the Promotion of Competition and Effective Consumer Defense, in aspects related to its field of application, absolute and relative monopolistic practices, the Commission to Promote Competition and sanctions.', 'This Law amends the Law for the Promotion of Competition and Effective Consumer Defense, in aspects related to its field of application, absolute and relative monopolistic practices, the Commission to Promote Competition and sanctions.', 'Costa Rica', 'governance', 'in_force', '2012-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_40', ARRAY['costa rica', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bb85a78b-6f58-5a32-9ad9-473fcc4dfd29', 'Costa Rica Law 9068 for Fiscal Transparency Compliance', 'Law 9068 for Fiscal Transparency Compliance', 'The "Ley para el cumplimiento del Estándar de Transparencia Fiscal N° 9068" was enacted in Costa Rica in 2012. The law aims to comply with the international standard of fiscal transparency, specifically related to the exchange of information for tax purposes. The law imposes obligations on businesses to provide accurate and complete information to the tax authorities, cooperate with tax audits, and maintain accounting records in accordance with the law. The law also provides for penalties and fines for non-compliance with these obligations.', 'The "Ley para el cumplimiento del Estándar de Transparencia Fiscal N° 9068" was enacted in Costa Rica in 2012. The law aims to comply with the international standard of fiscal transparency, specifically related to the exchange of information for tax purposes. The law imposes obligations on businesses to provide accurate and complete information to the tax authorities, cooperate with tax audits, and maintain accounting records in accordance with the law. The law also provides for penalties and fines for non-compliance with these obligations.', 'The "Ley para el cumplimiento del Estándar de Transparencia Fiscal N° 9068" was enacted in Costa Rica in 2012. The law aims to comply with the international standard of fiscal transparency, specifically related to the exchange of information for tax purposes. The law imposes obligations on businesses to provide accurate and complete information to the tax authorities, cooperate with tax audits, and maintain accounting records in accordance with the law. The law also provides for penalties and fines for non-compliance with these obligations.', 'Costa Rica', 'governance', 'in_force', '2012-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_42', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'costa rica']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('98e38ba7-f015-5dcf-9f5a-6c40b181e885', 'Costa Rica Law - General law on tobacco control', 'Law No. 9028 - General law on tobacco control and its harmful effects on health', 'The objective of this Law is to establish the necessary measures to protect people''s health from the health, social, environmental and economic consequences of tobacco consumption and exposure to tobacco smoke.', 'The objective of this Law is to establish the necessary measures to protect people''s health from the health, social, environmental and economic consequences of tobacco consumption and exposure to tobacco smoke.', 'The objective of this Law is to establish the necessary measures to protect people''s health from the health, social, environmental and economic consequences of tobacco consumption and exposure to tobacco smoke.', 'Costa Rica', 'governance', 'in_force', '2012-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_46', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'mandatory', 'costa rica', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e5a7d6fc-97f7-50c3-9331-dd5930566a06', 'Costa Rica Sustainable Public Procurement', 'Sustainable Public Procurement', 'This practical guide for sustainable purchasing in the public sector aims to provide public officials of institutional suppliers with tools to allow the incorporation of environmental and social criteria in their purchases.', 'This practical guide for sustainable purchasing in the public sector aims to provide public officials of institutional suppliers with tools to allow the incorporation of environmental and social criteria in their purchases.', 'This practical guide for sustainable purchasing in the public sector aims to provide public officials of institutional suppliers with tools to allow the incorporation of environmental and social criteria in their purchases.', 'Costa Rica', 'circularity', 'in_force', '2011-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_5', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'costa rica', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('04f725bd-4063-5922-a7b0-68e90c718c31', 'Costa Rica Decree 35368 Regulation for Controlled Agricultural Burns', 'Decree 35368 Regulation for Controlled Agricultural Burns', 'The "Reglamento para Quemas Agrícolas Controladas No 35368-MAG-S-MINAE" was issued in Costa Rica in 2009. The regulation establishes the guidelines and procedures to be followed by individuals and businesses who plan to carry out controlled agricultural burns. It sets out the obligations of businesses to obtain the necessary authorizations and to take steps to prevent the spread of fires and minimize their environmental impact. The regulation also requires businesses to monitor weather conditions and implement measures to minimize the risks associated with fires.', 'The "Reglamento para Quemas Agrícolas Controladas No 35368-MAG-S-MINAE" was issued in Costa Rica in 2009. The regulation establishes the guidelines and procedures to be followed by individuals and businesses who plan to carry out controlled agricultural burns. It sets out the obligations of businesses to obtain the necessary authorizations and to take steps to prevent the spread of fires and minimize their environmental impact. The regulation also requires businesses to monitor weather conditions and implement measures to minimize the risks associated with fires.', 'The "Reglamento para Quemas Agrícolas Controladas No 35368-MAG-S-MINAE" was issued in Costa Rica in 2009. The regulation establishes the guidelines and procedures to be followed by individuals and businesses who plan to carry out controlled agricultural burns. It sets out the obligations of businesses to obtain the necessary authorizations and to take steps to prevent the spread of fires and minimize their environmental impact. The regulation also requires businesses to monitor weather conditions and implement measures to minimize the risks associated with fires.', 'Costa Rica', 'climate', 'in_force', '2009-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_19', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'costa rica', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9391896d-7d49-5f26-8f31-b6de955e3312', 'Costa Rica S-H-MAG-MINAE Regulation for the control of substances', 'Decree 35676-S-H-MAG-MINAE Regulation for the control of substances that deplete the ozone layer (SAO) according to Law 7223 and its amendments', 'This Decree approves the Regulation for the control of substances that deplete the ozone layer (SAO), which aims to establish the measures and standards of mandatory compliance to control and reduce the use of substances that deplete the ozone layer (SAO) of according to the obligations assumed by Costa Rica with the ratification of the Montreal Protocol and its Amendments.', 'This Decree approves the Regulation for the control of substances that deplete the ozone layer (SAO), which aims to establish the measures and standards of mandatory compliance to control and reduce the use of substances that deplete the ozone layer (SAO) of according to the obligations assumed by Costa Rica with the ratification of the Montreal Protocol and its Amendments.', 'This Decree approves the Regulation for the control of substances that deplete the ozone layer (SAO), which aims to establish the measures and standards of mandatory compliance to control and reduce the use of substances that deplete the ozone layer (SAO) of according to the obligations assumed by Costa Rica with the ratification of the Montreal Protocol and its Amendments.', 'Costa Rica', 'climate', 'in_force', '2009-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_20', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'costa rica', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a961af73-12ba-562c-b0c2-ce6058bc24a1', 'Costa Rica Nº 35550-MINAE(*)-S-MOPT-MAG-MEIC (*) Amendment to the General', 'Nº 35550-MINAE(*)-S-MOPT-MAG-MEIC (*) Amendment to the General Regulations on Environmental Impact Assessment Procedures (EIA) in Intervention of Historical and Architectural Monuments', 'The modification to the General Regulation on Environmental Impact Assessment (EIA) Procedures in the Matter of Intervention of Historical and Architectural Monuments, published in 2009 in Costa Rica, does not impose specific obligations on businesses. However, it establishes the need for the competent authorities to consider the impact of any intervention in historical and architectural monuments on the environment and cultural heritage. Therefore, businesses that are planning to carry out activities that may impact historical and architectural monuments must comply with the EIA procedures established by this regulation and obtain the necessary permits from the competent authorities.', 'The modification to the General Regulation on Environmental Impact Assessment (EIA) Procedures in the Matter of Intervention of Historical and Architectural Monuments, published in 2009 in Costa Rica, does not impose specific obligations on businesses. However, it establishes the need for the competent authorities to consider the impact of any intervention in historical and architectural monuments on the environment and cultural heritage. Therefore, businesses that are planning to carry out activities that may impact historical and architectural monuments must comply with the EIA procedures established by this regulation and obtain the necessary permits from the competent authorities.', 'The modification to the General Regulation on Environmental Impact Assessment (EIA) Procedures in the Matter of Intervention of Historical and Architectural Monuments, published in 2009 in Costa Rica, does not impose specific obligations on businesses. However, it establishes the need for the competent authorities to consider the impact of any intervention in historical and architectural monuments on the environment and cultural heritage. Therefore, businesses that are planning to carry out activities that may impact historical and architectural monuments must comply with the EIA procedures established by this regulation and obtain the necessary permits from the competent authorities.', 'Costa Rica', 'climate', 'in_force', '2009-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_45', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'costa rica', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e859453d-5bb3-5bf9-9a04-4aa51fea11c3', 'Costa Rica Decree S -- Scrap Tire Regulations', 'Decree No. 33745-S -- Scrap Tire Regulations', 'The objective of this Regulation is to protect public health and the environment by establishing requirements, conditions and controls for the treatment of waste tires, which satisfy current health and environmental requirements.', 'The objective of this Regulation is to protect public health and the environment by establishing requirements, conditions and controls for the treatment of waste tires, which satisfy current health and environmental requirements.', 'The objective of this Regulation is to protect public health and the environment by establishing requirements, conditions and controls for the treatment of waste tires, which satisfy current health and environmental requirements.', 'Costa Rica', 'climate', 'in_force', '2007-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_18', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg12', 'costa rica', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2f00104b-157b-5a32-b23f-230c9333f737', 'Costa Rica Decree MINAE-S ─ Regulation of discharge and', 'Decree No. 33601-MINAE-S ─ Regulation of discharge and reuse of wastewater', 'This Decree approves the Regulation for the discharge and reuse of wastewater that, regardless of its origin, is discharged or reused, with the aim of protecting public health and the environment through environmentally sound wastewater management.', 'This Decree approves the Regulation for the discharge and reuse of wastewater that, regardless of its origin, is discharged or reused, with the aim of protecting public health and the environment through environmentally sound wastewater management.', 'This Decree approves the Regulation for the discharge and reuse of wastewater that, regardless of its origin, is discharged or reused, with the aim of protecting public health and the environment through environmentally sound wastewater management.', 'Costa Rica', 'climate', 'in_force', '2006-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_17', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'sdg12', 'costa rica', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5e237570-28a5-548e-83d5-4eefa2134d7f', 'Costa Rica Decrees S -- Prohibits the manufacture, import', 'Decrees No. 30050-S -- Prohibits the manufacture, import, transit, registration, marketing and use of raw material or manufactured product containing POLYCHLORINATED BIPHENYLS', 'The Decree No. 30050-S of Costa Rica in 2001 prohibits the manufacture, import, transit, registration, commercialization, and use of raw materials or products that contain polychlorinated biphenyls. The focus of the decree is to prevent the use of these chemicals that are hazardous to human health and the environment. Businesses in Costa Rica are obligated to comply with this decree and ensure that their products and raw materials do not contain polychlorinated biphenyls.', 'The Decree No. 30050-S of Costa Rica in 2001 prohibits the manufacture, import, transit, registration, commercialization, and use of raw materials or products that contain polychlorinated biphenyls. The focus of the decree is to prevent the use of these chemicals that are hazardous to human health and the environment. Businesses in Costa Rica are obligated to comply with this decree and ensure that their products and raw materials do not contain polychlorinated biphenyls.', 'The Decree No. 30050-S of Costa Rica in 2001 prohibits the manufacture, import, transit, registration, commercialization, and use of raw materials or products that contain polychlorinated biphenyls. The focus of the decree is to prevent the use of these chemicals that are hazardous to human health and the environment. Businesses in Costa Rica are obligated to comply with this decree and ensure that their products and raw materials do not contain polychlorinated biphenyls.', 'Costa Rica', 'climate', 'in_force', '2001-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_16', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'mandatory', 'costa rica', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d2931fc1-b3bd-54d4-a0ae-f08cf3c995b9', 'Costa Rica MINAE Regulations for the Handling of Industrial', 'Decree 27001-MINAE Regulations for the Handling of Industrial Dangerous Wastes', 'The "Reglamento para el Manejo de los Desechos Peligrosos Industriales N°27001-MINAE" was introduced in 1998 in Costa Rica to regulate the handling of hazardous industrial waste. The regulation imposes certain obligations on businesses that produce, transport, or dispose of hazardous waste. Businesses must obtain an environmental permit, keep records of waste generation and disposal, implement safety measures, and ensure that hazardous waste is transported by licensed carriers. The regulation also requires businesses to properly label and package hazardous waste and to submit annual reports on their waste management activities to the regulatory authorities.', 'The "Reglamento para el Manejo de los Desechos Peligrosos Industriales N°27001-MINAE" was introduced in 1998 in Costa Rica to regulate the handling of hazardous industrial waste. The regulation imposes certain obligations on businesses that produce, transport, or dispose of hazardous waste. Businesses must obtain an environmental permit, keep records of waste generation and disposal, implement safety measures, and ensure that hazardous waste is transported by licensed carriers. The regulation also requires businesses to properly label and package hazardous waste and to submit annual reports on their waste management activities to the regulatory authorities.', 'The "Reglamento para el Manejo de los Desechos Peligrosos Industriales N°27001-MINAE" was introduced in 1998 in Costa Rica to regulate the handling of hazardous industrial waste. The regulation imposes certain obligations on businesses that produce, transport, or dispose of hazardous waste. Businesses must obtain an environmental permit, keep records of waste generation and disposal, implement safety measures, and ensure that hazardous waste is transported by licensed carriers. The regulation also requires businesses to properly label and package hazardous waste and to submit annual reports on their waste management activities to the regulatory authorities.', 'Costa Rica', 'climate', 'in_force', '1998-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_15', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'sdg12', 'costa rica', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2063d685-917f-5d80-8dce-0694e2b21b70', 'Costa Rica Control and Technical Review of the emissions', 'Regulation for the Control and Technical Review of the emissions of polluting gases produced by Motor Vehicles Nº 28280 MOPT-MINAE-S', 'New and used vehicles with diesel or gasoline engines that enter the country after the entry into force of this Decree, must comply with the minimum gas emission standards established in the current Traffic Law or with the specifications of the European Economic Community or the Federal specifications of the United States of America under the procedure called US-FTP-75, as long as they do not contravene or are inferior to the provisions of the current Traffic Law.', 'New and used vehicles with diesel or gasoline engines that enter the country after the entry into force of this Decree, must comply with the minimum gas emission standards established in the current Traffic Law or with the specifications of the European Economic Community or the Federal specifications of the United States of America under the procedure called US-FTP-75, as long as they do not contravene or are inferior to the provisions of the current Traffic Law.', 'New and used vehicles with diesel or gasoline engines that enter the country after the entry into force of this Decree, must comply with the minimum gas emission standards established in the current Traffic Law or with the specifications of the European Economic Community or the Federal specifications of the United States of America under the procedure called US-FTP-75, as long as they do not contravene or are inferior to the provisions of the current Traffic Law.', 'Costa Rica', 'climate', 'in_force', '1996-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_14', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'costa rica', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4edf5f0a-dbf8-5c34-83d6-e07acd7d1bba', 'Costa Rica Decree MOPT-MEIC-S "Regulation for Land Transportation of', 'Decree No. 24715- MOPT-MEIC-S "Regulation for Land Transportation of Dangerous Products"', 'Automotive transport on public roads of any kind of dangerous product of a toxic, explosive, radioactive, oxidizing, flammable, corrosive, irritant or other nature, or that represents risks to the health of people, to public safety or the environment, will be subject to the rules and procedures, in the provisions of the legislation and discipline in particular for each product, and in accordance with what is established in these Regulations as well as by the legal regulations governing the matter.', 'Automotive transport on public roads of any kind of dangerous product of a toxic, explosive, radioactive, oxidizing, flammable, corrosive, irritant or other nature, or that represents risks to the health of people, to public safety or the environment, will be subject to the rules and procedures, in the provisions of the legislation and discipline in particular for each product, and in accordance with what is established in these Regulations as well as by the legal regulations governing the matter.', 'Automotive transport on public roads of any kind of dangerous product of a toxic, explosive, radioactive, oxidizing, flammable, corrosive, irritant or other nature, or that represents risks to the health of people, to public safety or the environment, will be subject to the rules and procedures, in the provisions of the legislation and discipline in particular for each product, and in accordance with what is established in these Regulations as well as by the legal regulations governing the matter.', 'Costa Rica', 'climate', 'in_force', '1995-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_13', ARRAY['other sustainability policy', 'regulations', 'sdg9', 'sdg11', 'mandatory', 'costa rica', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3d2eedd0-43ab-5d9f-bf6e-af39581cfc87', 'Costa Rica Decree S — Regulation on protection against', 'Decree No. 24037-S — Regulation on protection against ionizing radiation', 'This Decree approves the Regulation on protection against ionizing radiation, which aims to establish the criteria aimed at protecting the health of the population from radiological risks that may arise from the use of ionizing radiation and related activities.', 'This Decree approves the Regulation on protection against ionizing radiation, which aims to establish the criteria aimed at protecting the health of the population from radiological risks that may arise from the use of ionizing radiation and related activities.', 'This Decree approves the Regulation on protection against ionizing radiation, which aims to establish the criteria aimed at protecting the health of the population from radiological risks that may arise from the use of ionizing radiation and related activities.', 'Costa Rica', 'climate', 'in_force', '1994-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_24', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'costa rica', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
